local FishingLineSpoolMaker = {}
local PRODUCTS = {
    iron_fishinglinespool = { name = "Železni tulček za ribiško vrvico", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni tulček za ribiško vrvico za ribištvo." },
    bronze_fishinglinespool = { name = "Bronast tulček za ribiško vrvico", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast tulček za ribiško vrvico za ribištvo." },
    silver_fishinglinespool = { name = "Srebrn tulček za ribiško vrvico", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn tulček za ribiško vrvico za ribištvo." },
    gilded_fishinglinespool = { name = "Pozlačen tulček za ribiško vrvico", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen tulček za ribiško vrvico za ribištvo." },
    jewel_set_fishinglinespool = { name = "Draguljast tulček za ribiško vrvico", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast tulček za ribiško vrvico za ribištvo." },
    royal_sovereign_fishinglinespool = { name = "Kraljevski suveren tulček za ribiško vrvico", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren tulček za ribiško vrvico z biseri za krono." },
}
local BUILDINGS = {
    fishinglinespool_workshop = { name = "Fishinglinespool delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    fishinglinespool_house = { name = "Fishinglinespool hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_fishinglinespool_atelier = { name = "Mojstrski fishinglinespool atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_fishinglinespool_palace = { name = "Suverena fishinglinespool palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
FishingLineSpoolMaker.ironStock = 12; FishingLineSpoolMaker.bronzeStock = 10; FishingLineSpoolMaker.woodStock = 16; FishingLineSpoolMaker.leatherStock = 12; FishingLineSpoolMaker.silverStock = 8; FishingLineSpoolMaker.goldStock = 6; FishingLineSpoolMaker.jewelStock = 4; FishingLineSpoolMaker.pearlStock = 4
FishingLineSpoolMaker.productStock = {}; FishingLineSpoolMaker.buildings = {}; FishingLineSpoolMaker.maker = nil; FishingLineSpoolMaker.activeMaking = {}; FishingLineSpoolMaker.totalProducts = 0; FishingLineSpoolMaker.dayTimer = 0
function FishingLineSpoolMaker.init() FishingLineSpoolMaker.ironStock=12; FishingLineSpoolMaker.bronzeStock=10; FishingLineSpoolMaker.woodStock=16; FishingLineSpoolMaker.leatherStock=12; FishingLineSpoolMaker.silverStock=8; FishingLineSpoolMaker.goldStock=6; FishingLineSpoolMaker.jewelStock=4; FishingLineSpoolMaker.pearlStock=4; FishingLineSpoolMaker.productStock={}; FishingLineSpoolMaker.buildings={}; FishingLineSpoolMaker.maker=nil; FishingLineSpoolMaker.activeMaking={}; FishingLineSpoolMaker.totalProducts=0; FishingLineSpoolMaker.dayTimer=0; print("[FishingLineSpoolMaker] Royal Fishing Line Spool Maker System initialized (6 products, 4 buildings)") end
function FishingLineSpoolMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; FishingLineSpoolMaker.maker={name=n or ("Navijalec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Navijalec najet: %s (spretnost: %d)",FishingLineSpoolMaker.maker.name,s),"success") end; return true end
function FishingLineSpoolMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function FishingLineSpoolMaker.build(id) local ok,e=FishingLineSpoolMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(FishingLineSpoolMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function FishingLineSpoolMaker.getQualityBonus() local b=0; for _,bd in ipairs(FishingLineSpoolMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function FishingLineSpoolMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and FishingLineSpoolMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and FishingLineSpoolMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and FishingLineSpoolMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and FishingLineSpoolMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and FishingLineSpoolMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and FishingLineSpoolMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and FishingLineSpoolMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and FishingLineSpoolMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #FishingLineSpoolMaker.buildings==0 then return false,"Potrebna navijalna delavnica" end; if not FishingLineSpoolMaker.maker then return false,"Potreben navijalec" end; return true end
function FishingLineSpoolMaker.make(pt,qty) qty=qty or 1; local ok,e=FishingLineSpoolMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then FishingLineSpoolMaker.ironStock=FishingLineSpoolMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then FishingLineSpoolMaker.bronzeStock=FishingLineSpoolMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then FishingLineSpoolMaker.woodStock=FishingLineSpoolMaker.woodStock-d.woodCost*qty end; if d.leatherCost then FishingLineSpoolMaker.leatherStock=FishingLineSpoolMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then FishingLineSpoolMaker.silverStock=FishingLineSpoolMaker.silverStock-d.silverCost*qty end; if d.goldCost then FishingLineSpoolMaker.goldStock=FishingLineSpoolMaker.goldStock-d.goldCost*qty end; if d.jewelCost then FishingLineSpoolMaker.jewelStock=FishingLineSpoolMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then FishingLineSpoolMaker.pearlStock=FishingLineSpoolMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if FishingLineSpoolMaker.maker then t=math.max(1,t-math.floor(FishingLineSpoolMaker.maker.skill/13)) end; table.insert(FishingLineSpoolMaker.activeMaking,{id="${MAKER_LOWER}_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function FishingLineSpoolMaker.completeMaking(m) local q=1.0+(FishingLineSpoolMaker.getQualityBonus()/100); if FishingLineSpoolMaker.maker then q=q+(FishingLineSpoolMaker.maker.skill/140) end; q=math.min(2.5,q); FishingLineSpoolMaker.productStock[m.productType]=(FishingLineSpoolMaker.productStock[m.productType] or 0)+m.quantity; FishingLineSpoolMaker.totalProducts=FishingLineSpoolMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if FishingLineSpoolMaker.maker then FishingLineSpoolMaker.maker.itemsMade=FishingLineSpoolMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then FishingLineSpoolMaker.maker.skill=math.min(100,FishingLineSpoolMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Tulček izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"${MAKER_LOWER}.completed",{productName=m.productName,prestige=m.prestige,happiness:m.happiness}) end end
function FishingLineSpoolMaker.update(dt) if not _G.state then return end; FishingLineSpoolMaker.dayTimer=FishingLineSpoolMaker.dayTimer+dt; if FishingLineSpoolMaker.dayTimer>=30 then FishingLineSpoolMaker.dayTimer=0; for i=#FishingLineSpoolMaker.activeMaking,1,-1 do local m=FishingLineSpoolMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then FishingLineSpoolMaker.completeMaking(m); table.remove(FishingLineSpoolMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(FishingLineSpoolMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if FishingLineSpoolMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function FishingLineSpoolMaker.getStats() return {ironStock=FishingLineSpoolMaker.ironStock,bronzeStock=FishingLineSpoolMaker.bronzeStock,woodStock=FishingLineSpoolMaker.woodStock,leatherStock=FishingLineSpoolMaker.leatherStock,silverStock=FishingLineSpoolMaker.silverStock,goldStock=FishingLineSpoolMaker.goldStock,jewelStock=FishingLineSpoolMaker.jewelStock,pearlStock=FishingLineSpoolMaker.pearlStock,productStock=FishingLineSpoolMaker.productStock,numBuildings=#FishingLineSpoolMaker.buildings,hasMaker=FishingLineSpoolMaker.maker~=nil,makerName=FishingLineSpoolMaker.maker and FishingLineSpoolMaker.maker.name or "—",makerSkill=FishingLineSpoolMaker.maker and FishingLineSpoolMaker.maker.skill or 0,activeMaking=#FishingLineSpoolMaker.activeMaking,totalProducts=FishingLineSpoolMaker.totalProducts} end
return FishingLineSpoolMaker
